def get(self) -> "QueueGetResult":
    """Get the next queued experiment.

    Returns:
        QueueGetResult containing the queue entry and executor.
    """
    for msg, entry in self._iter_queued():
        msg.ack()  # Remove from queue
        executor = self.init_executor(self.repo.experiments, entry)
        return QueueGetResult(entry, executor)
    return None

